// src/App.js
import React, { useState, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faTimes, faPlus, faBoxOpen, faUserCircle, faMicrophone } from '@fortawesome/free-solid-svg-icons';
import * as chrono from 'chrono-node';
import './App.css';

function App() {
  const [products, setProducts] = useState([]);
  const [productName, setProductName] = useState('');
  const [expiryDate, setExpiryDate] = useState('');
  const [listening, setListening] = useState(false);
  const [editing, setEditing] = useState({ id: null, field: null });
  const [editValue, setEditValue] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [savedEmail, setSavedEmail] = useState('');
  const [notify, setNotify] = useState(true);
  const [emailMsg, setEmailMsg] = useState('');
  const recognitionRef = useRef(null);

  const addProduct = () => {
    if (productName.trim() && expiryDate) {
      const newProduct = {
        id: Date.now(),
        productName: productName.trim(),
        expiryDate,
        addedDate: new Date().toISOString().split('T')[0]
      };
      setProducts([...products, newProduct]);
      setProductName('');
      setExpiryDate('');
    }
  };

  const removeProduct = (id) => {
    setProducts(products.filter(product => product.id !== id));
  };

  const getExpiryStatus = (expiryDate) => {
    const today = new Date();
    const expiry = new Date(expiryDate);
    const daysUntilExpiry = Math.ceil((expiry - today) / (1000 * 60 * 60 * 24));

    if (daysUntilExpiry < 0) {
      return { status: 'expired', text: 'EXPIRED', days: Math.abs(daysUntilExpiry) };
    } else if (daysUntilExpiry <= 7) {
      return { status: 'warning', text: `${daysUntilExpiry} DAYS LEFT`, days: daysUntilExpiry };
    } else {
      return { status: 'good', text: 'GOOD', days: daysUntilExpiry };
    }
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const isFormValid = productName.trim() && expiryDate;

  // Voice input logic
  const handleVoiceInput = () => {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      alert('Sorry, your browser does not support speech recognition.');
      return;
    }
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    setListening(true);
    recognitionRef.current = recognition;
    recognition.onresult = (event) => {
      const transcript = event.results[0][0].transcript;
      // Use chrono-node to parse date
      const results = chrono.parse(transcript);
      if (results.length > 0) {
        const date = results[0].start.date();
        const dateISO = date.toISOString().split('T')[0];
        setExpiryDate(dateISO);
        // Remove the date part from the product name
        const product = transcript.replace(results[0].text, '').replace(/,|expires|exp|expiry|date/gi, '').trim();
        setProductName(product);
      } else {
        setProductName(transcript);
      }
      setListening(false);
    };
    recognition.onerror = () => {
      setListening(false);
    };
    recognition.onend = () => {
      setListening(false);
    };
    recognition.start();
  };

  const stopVoiceInput = () => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setListening(false);
    }
  };

  // Inline editing logic
  const handleEdit = (id, field, value) => {
    setEditing({ id, field });
    setEditValue(value);
  };

  const handleEditChange = (e) => {
    setEditValue(e.target.value);
  };

  const handleEditSave = () => {
    setProducts(products.map(product => {
      if (product.id === editing.id) {
        if (editing.field === 'productName') {
          return { ...product, productName: editValue };
        } else if (editing.field === 'expiryDate') {
          return { ...product, expiryDate: editValue };
        }
      }
      return product;
    }));
    setEditing({ id: null, field: null });
    setEditValue('');
  };

  const handleEditKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleEditSave();
    } else if (e.key === 'Escape') {
      setEditing({ id: null, field: null });
      setEditValue('');
    }
  };

  const handleEditBlur = () => {
    handleEditSave();
  };

  // Email save logic
  const handleSaveEmail = (e) => {
    e.preventDefault();
    if (!userEmail || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(userEmail)) {
      setEmailMsg('Please enter a valid email address.');
      return;
    }
    setSavedEmail(userEmail);
    setEmailMsg('Email saved! You will be notified before expiry.');
    setTimeout(() => setEmailMsg(''), 3000);
  };

  return (
    <>
      <div className="appbar">
        <div className="appbar-title">
          <FontAwesomeIcon icon={faBoxOpen} size="lg" />
          FreshTrack Pro
        </div>
        <div className="appbar-profile">
          <FontAwesomeIcon icon={faUserCircle} size="lg" />
        </div>
      </div>
      <div className="App">
        <div className="workspace">
          <form className="email-form" onSubmit={handleSaveEmail}>
            <label htmlFor="userEmail" className="email-label">Email for expiry notifications:</label>
            <input
              type="email"
              id="userEmail"
              className="email-input"
              placeholder="Enter your email"
              value={userEmail}
              onChange={e => setUserEmail(e.target.value)}
              autoComplete="email"
            />
            <label className="notify-label">
              <input
                type="checkbox"
                checked={notify}
                onChange={e => setNotify(e.target.checked)}
              /> Notify me before expiry
            </label>
            <button className="email-save-btn" type="submit">Save Email</button>
            {emailMsg && <div className="email-msg">{emailMsg}</div>}
          </form>

          <form className="add-product" onSubmit={e => { e.preventDefault(); addProduct(); }}>
            <div className="form-group" style={{ minWidth: 0, flex: 1 }}>
              <label htmlFor="productName">Product Name</label>
              <input
                type="text"
                id="productName"
                placeholder="Enter product name"
                value={productName}
                onChange={(e) => setProductName(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && isFormValid && addProduct()}
                style={{ flex: 1 }}
              />
            </div>
            <div className="form-group">
              <label htmlFor="expiryDate">Expiry Date</label>
              <input
                type="date"
                id="expiryDate"
                value={expiryDate}
                onChange={(e) => setExpiryDate(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && isFormValid && addProduct()}
              />
            </div>
            <button 
              className="add-button" 
              type="submit"
              disabled={!isFormValid}
            >
              <FontAwesomeIcon icon={faPlus} style={{ marginRight: '8px' }} />
              Add Product
            </button>
          </form>

          <div className="voice-section">
            <div className="voice-instructions">
              <hr className="voice-divider" />
              <div>Or use voice input:</div>
              <div className="voice-example">Say both product name and expiry date, e.g. <b>"Milk July 20 2024"</b></div>
            </div>
            <div className="voice-mic-row">
              <button
                type="button"
                className={`voice-button-modern${listening ? ' listening' : ''}`}
                title="Voice input"
                onClick={listening ? stopVoiceInput : handleVoiceInput}
              >
                <FontAwesomeIcon icon={faMicrophone} />
              </button>
              <div className="voice-mic-label">{listening ? 'Listening...' : 'Tap to speak'}</div>
            </div>
          </div>

          <div className="content-panel">
            <h2><FontAwesomeIcon icon={faBoxOpen} style={{ color: '#2563eb' }} /> Products List</h2>
            {products.length === 0 ? (
              <div className="empty-state">
                <h3>No products added yet</h3>
                <p>Start by adding your first product using the form above.</p>
              </div>
            ) : (
              <table className="products-table">
                <thead>
                  <tr>
                    <th>Product Name</th>
                    <th>Expiry Date</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {products.map((product) => {
                    const expiryStatus = getExpiryStatus(product.expiryDate);
                    return (
                      <tr key={product.id}>
                        <td
                          onDoubleClick={() => handleEdit(product.id, 'productName', product.productName)}
                          style={{ cursor: 'pointer' }}
                        >
                          {editing.id === product.id && editing.field === 'productName' ? (
                            <input
                              type="text"
                              value={editValue}
                              autoFocus
                              onChange={handleEditChange}
                              onBlur={handleEditBlur}
                              onKeyDown={handleEditKeyDown}
                              style={{ minWidth: 80 }}
                            />
                          ) : (
                            product.productName
                          )}
                        </td>
                        <td
                          onDoubleClick={() => handleEdit(product.id, 'expiryDate', product.expiryDate)}
                          style={{ cursor: 'pointer' }}
                        >
                          {editing.id === product.id && editing.field === 'expiryDate' ? (
                            <input
                              type="date"
                              value={editValue}
                              autoFocus
                              onChange={handleEditChange}
                              onBlur={handleEditBlur}
                              onKeyDown={handleEditKeyDown}
                              style={{ minWidth: 120 }}
                            />
                          ) : (
                            formatDate(product.expiryDate)
                          )}
                        </td>
                        <td>
                          <span className={`expiry-status ${expiryStatus.status}`}>
                            {expiryStatus.text}
                          </span>
                        </td>
                        <td>
                          <button 
                            className="delete-button"
                            onClick={() => removeProduct(product.id)}
                            title="Remove product"
                          >
                            <FontAwesomeIcon icon={faTimes} />
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        </div>
        <div className="footer">
          &copy; {new Date().getFullYear()} FreshTrack Pro &mdash; Product Expiry SaaS | Powered by React | <a href="#" style={{color:'#2563eb',textDecoration:'none'}}>Contact Support</a>
        </div>
      </div>
    </>
  );
}

export default App;
